pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = (step_index as f64 / total_items as f64).powi(2);
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let compaction_factor = if bin_residual < mean_residual * 1.2 { 0.95 } else if bin_residual > mean_residual * 3.0 { 0.6 } else { 1.0 };
    let score = (1.0 - (1.2 * stream_progress + 0.4) * residual_ratio.powi(2)) * compaction_factor;
    let score = score * 0.75 + ((score * 0.90 + ((post_residual as f64 / bin_capacity as f64) as f64) * 0.1) as f64) * 0.25;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = (step_index as f64 / total_items as f64).powi(3);
    let fitting_penalty = if fitting_bins_count > 2 { 0.85 } else { 1.1 };
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let compaction_factor = if bin_residual < mean_residual * 1.2 {
        0.9
    } else if bin_residual < mean_residual * 2.5 {
        0.8
    } else {
        1.0
    };
    let lookahead_factor = if fitting_bins_count > 3 {
        1.0
    } else {
        (fitting_bins_count as f64).powi(3) / 8.0
    };

    // Horizontal Swarm Crossover Mutations
    let new_compaction_factor = if bin_residual < mean_residual * 1.4 {
        0.85
    } else if bin_residual < mean_residual * 2.4 {
        0.75
    } else {
        0.9
    };
    let new_lookahead_factor = if fitting_bins_count > 3 {
        1.1
    } else {
        (fitting_bins_count as f64).powi(2) / 7.0
    };

    let score = (1.0 - stream_progress * residual_ratio.powi(2)) * new_compaction_factor * new_lookahead_factor;
    let score = score * 0.95 + ((if bin_residual < next_item_size { 0.9 } else { 1.0 }) as f64) * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = (step_index as f64 / total_items as f64).powi(3);
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let score = 1.0 - (2.0 * stream_progress + 0.5) * residual_ratio.powi(4);

    // Introduce lookahead trade-offs and fine-tuned thresholds
    let lookahead_factor = if post_residual < mean_residual { 1.3 } else { 0.7 };
    let score = score * lookahead_factor;

    // Adjust the penalty based on fitting_bins_count
    let fitting_penalty = if fitting_bins_count > 2 { 0.85 } else { 1.1 };
    let score = score * fitting_penalty;

    // Introduce non-linear conditionals and fine-tuned thresholds
    let item_size_ratio = item_size as f64 / bin_capacity as f64;
    let score = if item_size_ratio < 0.3 {
        score * 1.2
    } else if item_size_ratio > 0.7 {
        score * 0.8
    } else {
        score
    };

    // Adjust the penalty based on bin_residual and next_item_size
    let residual_next_item_penalty = if bin_residual < next_item_size { 0.9 } else { 1.0 };
    let score = score * residual_next_item_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = (step_index as f64 / total_items as f64).powi(3);
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Horizontal Swarm Crossover
    let lookahead_factor = if post_residual < mean_residual { 1.5 } else { 0.8 };
    let fitting_penalty = if fitting_bins_count > 2 { 0.9 } else { 1.2 };

    // Non-linear conditionals and thresholds
    let score = 1.0 - (3.0 * stream_progress + 1.0) * residual_ratio.powi(5);
    let item_size_ratio = item_size as f64 / bin_capacity as f64;
    let penalty_factor = if item_size_ratio < 0.2 { 1.3 } else if item_size_ratio > 0.8 { 0.7 } else { 1.0 };

    // Lookahead trade-offs
    let residual_next_item_penalty = if bin_residual < next_item_size * 0.5 { 0.95 } else { 1.0 };

    // Final score calculation with combined factors
    let score = score * lookahead_factor * fitting_penalty * penalty_factor * residual_next_item_penalty;
    let score = score * 0.9 + ((post_residual as f64 / bin_capacity as f64) as f64) * 0.1;

    score
}
